import json, sys, io, contextlib, signal, re, glob, os
import pandas as pd

class TO(Exception): pass
def handler(s,f): raise TO()
signal.signal(signal.SIGALRM, handler)

def post_process(text):
    if "```" in text:
        blocks = re.findall(r"```(.*?)```", text, re.DOTALL)
        if len(blocks) == 0:
            text = text.split("```")[1]
        else:
            text = blocks[0]
            if not text.startswith("\n"):
                text = text[max(text.find("\n") + 1, 0):]
    return text

def run_one(code, inp, timeout=5):
    ns = {'__name__':'__main__'}
    old_stdin = sys.stdin
    buf = io.StringIO()
    try:
        sys.stdin = io.StringIO(inp)
        with contextlib.redirect_stdout(buf):
            signal.alarm(timeout)
            try:
                exec(compile(code, '<sol>', 'exec'), ns)
            finally:
                signal.alarm(0)
    except TO:
        return None, 'timeout'
    except Exception as e:
        return None, f'exc:{type(e).__name__}:{e}'
    finally:
        sys.stdin = old_stdin
    return buf.getvalue(), None

def norm(s):
    return '\n'.join(x.rstrip() for x in s.strip().splitlines())

def ci(s):
    return norm(s).lower()

if __name__ == '__main__':
    pid = sys.argv[1]
    tr = pd.read_parquet('/workspace/taco_verl/train.parquet')
    row = None
    for _, r in tr.iterrows():
        if r.extra_info['problem_id'] == pid:
            row = r; break
