    content = row.prompt[0]['content']
    gt = json.loads(row.reward_model['ground_truth'])
    code = None
    for p in glob.glob('/workspace/rollout_data/*.jsonl'):
        for l in open(p):
            rr = json.loads(l)
            if rr['input'][5:-11] == content:
                code = post_process(rr['output']); pr = float(rr['pass_rate'])
                if code: break
        if code: break
    print('pid', pid, 'ntests', len(gt['inputs']), 'nrollout_pr', pr)
    fails = []
    for i, inp in enumerate(gt['inputs']):
        if isinstance(inp, list): inp = '\n'.join(inp)
