def parse_block(b):
    d={}
    r=b['raw']
    m=re.search(r'split=(\w+) step=(\d+) idx=(\d+)',r[0])
    if not m: return None
    d['split'],d['step'],d['idx']=m.group(1),int(m.group(2)),int(m.group(3))
    for l in r[1:3]:
        mm=re.search(r'problem_id=(\S+) code_type=(\S+)',l)
        if mm: d['pid']=mm.group(1)
    # expected: after [expected] marker line until [output]
    exp=None; out=None
