import pandas as pd, json
from collections import defaultdict
def blocks(seq, key):
    idx=[i for i,x in enumerate(seq) if key(x)]
    if not idx: return []
    runs=[]; s=idx[0]; p=idx[0]
    for i in idx[1:]:
        if i==p+1: p=i
        else: runs.append((s,p)); s=i; p=i
    runs.append((s,p)); return runs
for split in ['train','test']:
    df=pd.read_parquet(f'taco_verl/{split}.parquet')
    print('=====',split)
    for _,r in df.iterrows():
        gt=json.loads(r['reward_model']['ground_truth'])
        outs=[o.strip() if isinstance(o,str) else json.dumps(o) for o in gt['outputs']]
        g=defaultdict(set)
        for o in outs: g[o.lower()].add(o)
        if not any(len(v)>1 for v in g.values()): continue
        # style per index: lower if the raw output contains lowercase and no uppercase, upper if avoids lowercase
        styles=[]
        for o in outs:
            letters=[c for c in o if c.isalpha()]
            if any(c.islower() for c in letters) and not any(c.isupper() for c in letters): styles.append('l')
            elif any(c.isupper() for c in letters) and not any(c.islower() for c in letters): styles.append('U')
            else: styles.append('?')
        lb=blocks(styles,lambda x:x=='l'); ub=blocks(styles,lambda x:x=='U')
        print(r['extra_info']['problem_id'],'n=%d'%len(outs),'lower_blocks=',lb[:6],'nlow=%d'%sum(1 for x in styles if x=='l'),'nU=%d'%sum(1 for x in styles if x=='U'))
