    if l and l.startswith('[TACO-FAIL]'):
        b={'head':l}
        j=i+1; cur=None
        while j<len(cl):
            x=cl[j]
            if x is None or x.startswith('========') or x.startswith('[TACO-FAIL]'): break
            if x.startswith('problem_id='):
                b['pid']=x.split('problem_id=')[1].split()[0]
            elif x.startswith('n_pass/n_tests='):
                mm=re.match(r'n_pass/n_tests=(\d+)/(\d+) fail_index=(\d+)',x)
                if mm: b['npass'],b['ntests'],b['fi']=map(int,mm.groups())
            elif x.startswith('[code]'): cur='code'
            elif x.startswith('[input]'): cur='input'
            elif x.startswith('[expected]'): cur='expected'; b.setdefault('expected',[]).append(x[len('[expected]'):])
