import subprocess, sys, json, re
from collections import Counter
pids=['train913','train15426','train23215','train7971','train20246','train20767','train11353']
def norm(s):
    s=str(s).strip()
    try:
        v=json.loads(s)
        if isinstance(v,list): return '\n'.join(str(x) for x in v).strip()
    except Exception: pass
    return s
def cl(e,o):
    e=norm(e); o=norm(o)
    if e==o: return 'exact'
    if e.lower()==o.lower(): return 'case'
    if re.sub(r'\s+',' ',e.lower())==re.sub(r'\s+',' ',o.lower()): return 'ws'
    return 'real'
for pid in pids:
    try:
        out=subprocess.run([sys.executable,'-I','/tmp/probe/detail.py',pid],capture_output=True,text=True,timeout=240)
        line=[l for l in out.stdout.strip().splitlines() if l.startswith('{')]
        if not line: print(pid,'no out',out.stderr[-200:]); continue
        d=json.loads(line[-1])
        cc=Counter(); ex=[]
        for f in d.get('fails',[]):
            if f.get('output') is None: cc['none']+=1
            else:
                k=cl(f.get('expected',''),f['output']); cc[k]+=1
                if k in ('case','ws') and len(ex)<3: ex.append((f['index'],str(f.get('expected'))[:50],str(f['output'])[:80]))
        print(pid,'pr',round(d.get('resp_pass_rate',-1),3),'n',d.get('ntests'),'nfail',d.get('nfail'),dict(cc),ex)
    except Exception as e:
        print(pid,'ERR',repr(e)[:100])
