import pandas as pd, json, collections, re, glob
tr=pd.read_parquet('taco_verl/train.parquet')
rows={r['extra_info']['problem_id']:r for _,r in tr.iterrows()}
cmap={r['prompt'][0]['content']:pid for pid,r in rows.items()}
maxpr={}
for p in sorted(glob.glob('rollout_data/*.jsonl')):
    for l in open(p):
        rr=json.loads(l); pid=cmap.get(rr['input'][5:-11])
        if pid: maxpr[pid]=max(maxpr.get(pid,-1),rr['pass_rate'])
def style(s):
    letters=[ch for ch in s if ch.isalpha()]
    if not letters: return None
    if s==s.upper() and s!=s.lower(): return 'U'
    if s==s.lower() and s!=s.upper(): return 'L'
    return 'M'
groups=collections.defaultdict(list)
for pid,r in rows.items():
    outs=[str(o) for o in json.loads(r['reward_model']['ground_truth'])['outputs']]
    toks=[]
    for o in outs:
        for t in re.split(r'\s+',o):
            if t and any(ch.isalpha() for ch in t): toks.append(t)
    if not toks: continue
    yn=[t for t in toks if t.lower() in ('yes','no')]
    if len(yn)<0.95*len(toks): continue
    styles=set(style(t) for t in yn)
    forms=collections.Counter(t for t in yn)
