    for l in open(p):
        rr=json.loads(l); pid=cmap.get(rr['input'][5:-11])
        if pid: maxpr[pid]=max(maxpr.get(pid,-1),rr['pass_rate'])

def variant_levels(outs):
    # whole
    g=collections.defaultdict(set)
    for o in outs:
        s=o.strip()
        if any(ch.isalpha() for ch in s): g[s.casefold()].add(s)
    if any(len(v)>1 for v in g.values()): return 'whole'
    # line
    g2=collections.defaultdict(set)
    for o in outs:
        for ln in o.split('\n'):
            s=ln.strip()
            if any(ch.isalpha() for ch in s): g2[s.casefold()].add(s)
    if any(len(v)>1 for v in g2.values()): return 'line'
    # token
    g3=collections.defaultdict(set)
    for o in outs:
        for t in re.split(r'\s+',o):
            if t and any(ch.isalpha() for ch in t): g3[t.casefold()].add(t)
    if any(len(v)>1 for v in g3.values()): return 'token'
    return None

var_rows=[]
for pid,r in rows.items():
    outs=[str(o) for o in json.loads(r['reward_model']['ground_truth'])['outputs']]
    lvl=variant_levels(outs)
