import json, subprocess, sys, re, glob
import pandas as pd
from concurrent.futures import ThreadPoolExecutor

sys.path.insert(0,'/workspace')
tr=pd.read_parquet('/workspace/taco_verl/train.parquet')
rows={r['extra_info']['problem_id']:r for _,r in tr.iterrows()}
cmap={r['prompt'][0]['content']:pid for pid,r in rows.items()}
maxpr={}
for p in sorted(glob.glob('/workspace/rollout_data/*.jsonl')):
    for l in open(p):
        rr=json.loads(l); pid=cmap.get(rr['input'][5:-11])
        if pid: maxpr[pid]=max(maxpr.get(pid,-1),rr['pass_rate'])
zeros=sorted([p for p,v in maxpr.items() if v==0])
print('zero pids',len(zeros),flush=True)

def norm(s):
    s=str(s).strip()
    try:
        v=json.loads(s)
        if isinstance(v,list): return '\n'.join(str(x) for x in v).strip()
    except Exception: pass
    return s
def cl(e,o):
    e=norm(e); o=norm(o)
    if e==o: return 'exact'
    if e.lower()==o.lower(): return 'case'
    if re.sub(r'\s+',' ',e.lower())==re.sub(r'\s+',' ',o.lower()): return 'ws'
    return 'real'

def one(pid):
    try:
        out=subprocess.run([sys.executable,'-I','/tmp/probe/detail.py',pid],capture_output=True,text=True,timeout=400)
        lines=[l for l in out.stdout.strip().splitlines() if l.startswith('{')]
        if not lines: return {'pid':pid,'err':'noout','stderr':out.stderr[-200:]}
        d=json.loads(lines[-1])
        from collections import Counter
        cc=Counter(); ex=[]
        for f in d.get('fails',[]):
            if f.get('output') is None: cc['none']+=1
            else:
                k=cl(f.get('expected',''),f['output']); cc[k]+=1
                if k in ('case','ws') and len(ex)<3: ex.append({'i':f['index'],'e':str(f.get('expected'))[:60],'o':str(f['output'])[:90]})
        return {'pid':pid,'pr':d.get('resp_pass_rate'),'n':d.get('ntests'),'nf':d.get('nfail'),'cc':dict(cc),'ex':ex}
    except Exception as e:
        return {'pid':pid,'err':repr(e)[:150]}

with ThreadPoolExecutor(max_workers=6) as ex:
    for r in ex.map(one,zeros):
        print(json.dumps(r),flush=True)
