import json,re,sys
import pandas as pd
from collections import Counter
path=sys.argv[1]
df=pd.read_parquet(path)
def styles_of(tok):
    s=set()
    if tok==tok.upper() and tok!=tok.lower(): s.add('U')
    if tok==tok.lower() and tok!=tok.upper(): s.add('L')
    if tok.istitle(): s.add('T')
    return s
def analyze(row):
    d=json.loads(row.reward_model['ground_truth']); outs=d['outputs']
    stmt=row.prompt[0]['content']
    # token -> style counts in outputs
    oc=Counter(); ostyle={}
    for o in outs:
        if not isinstance(o,str): continue
        for w in re.findall(r'[A-Za-z]{2,}',o):
            oc[w.lower()]+=1
    # statement occurrences
    sc=Counter(); sstyle={}
    for w in re.findall(r'[A-Za-z]{2,}',stmt):
        sc[w.lower()]+=1
        for s in styles_of(w): sstyle.setdefault(w.lower(),Counter())[s]+=1
    flags=[]
    for w,n in oc.items():
        if n<3: continue
        # gather output styles for this token
        ostyles=Counter()
        for o in outs:
            if not isinstance(o,str): continue
            for x in re.findall(r'[A-Za-z]{2,}',o):
                if x.lower()==w:
                    for s in styles_of(x): ostyles[s]+=1
        if not ostyles: continue
        dom=ostyles.most_common(1)[0][0]
        if w in sstyle and sstyle[w].get(dom,0)==0:
            flags.append((w,dom,dict(ostyles),dict(sstyle[w])))
    return flags
cnt=0
for _,row in df.iterrows():
    f=analyze(row)
    if f:
        cnt+=1
        print(row.extra_info['problem_id'], 'n=',len(json.loads(row.reward_model['ground_truth'])['outputs']), f[:3])
print('FLAGGED',cnt)
PYEOF
