import json,re,sys
import pandas as pd
from collections import Counter
path=sys.argv[1]
df=pd.read_parquet(path)
def styles_of(tok):
    s=set()
    if tok==tok.upper() and tok!=tok.lower(): s.add('U')
    if tok==tok.lower() and tok!=tok.upper(): s.add('L')
    if tok.istitle(): s.add('T')
    return s or {'M'}
def analyze(row):
    d=json.loads(row.reward_model['ground_truth']); outs=d['outputs']
    if not outs or not isinstance(outs[0],str): return []
    stmt=row.prompt[0]['content']; sc=Counter()
    for w in re.findall(r'[A-Za-z]{2,}',stmt):
        for s in styles_of(w): sc[(w.lower(),s)]+=1
    # tokens in GT[0]
    flags=[]
    seen=set()
    for w in re.findall(r'[A-Za-z]{2,}',outs[0]):
        lw=w.lower()
        if lw in seen: continue
        seen.add(lw)
        st=styles_of(w)
        if not any(sc.get((lw,s),0)>0 for s in st):
            # GT[0] style absent in statement for this token
            ocur=Counter()
            for o in outs:
                if isinstance(o,str):
                    for x in re.findall(r'[A-Za-z]{2,}',o):
                        if x.lower()==lw:
                            for s in styles_of(x): ocur[s]+=1
            flags.append((w,sorted(st),dict(ocur)))
    return flags
cnt=0
for _,row in df.iterrows():
    f=analyze(row)
    if f:
        cnt+=1
